class SimpleBuildAction(BaseModel):
    """模型只决定执行动作，不承担独立检查的输出断言。"""

    model_config = ConfigDict(extra="forbid")
    step_id: str = Field(pattern=r"^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")
    role: Literal["dependency", "configure", "build"]
    command: str = Field(min_length=1)
    workdir: str = "/workspace/repo"
    requires: tuple[str, ...] = ()
    source: str = Field(min_length=1, description="已读取的作者说明或构建文件及位置")
    expected: str = Field(min_length=1, description="此动作的目的，仅为说明")

    @model_validator(mode="before")
    @classmethod
    def discard_diagnostic_hint(cls, value):
        # 诊断提示不参与执行；仅丢弃这一字段，其余未知字段与动作安全校验保持严格。
        # 原模型响应由meter保留，不修改或执行提示里的路径。
        if isinstance(value, dict) and "diagnostic_paths" in value:
            return {key: item for key, item in value.items() if key != "diagnostic_paths"}
        return value

class SimpleBuildActions(BaseModel):
    model_config = ConfigDict(extra="forbid")
    reason: str = Field(min_length=1, description="简短说明构建入口及选项依据，不是步骤列表")
    steps: list[SimpleBuildAction] = Field(min_length=1)
    build_directory: str | None = Field(default=None, description="有作者依据时提供主项目构建目录，使用/workspace/repo内规范绝对路径；仅辅助观察，不改变workdir或作为成功断言")
    discard_dependencies: dict[str, str] = Field(default_factory=dict, description="仅恢复时使用：显式废弃或替换已成功依赖步骤的step_id及非空理由；未声明的成功依赖由系统保留，不能因当前容器已有而省掉重放安装")

    @field_validator("discard_dependencies")
    @classmethod
    def valid_discards(cls, value):
        if any(not key.strip() or not reason.strip() for key, reason in value.items()):
            raise ValueError("废弃依赖必须提供步骤标识和非空理由")
        return value

    @field_validator("build_directory")
    @classmethod
    def valid_directory(cls, value):
        if value is not None:
            PlanStep.validate_workdir(value)
            if not value.startswith("/workspace/repo/") and value != "/workspace/repo":
                raise ValueError("构建目录必须在/workspace/repo内")
        return value

    @model_validator(mode="after")
    def valid_execution(self) -> Self:
        # 使用成熟的动作/顺序校验，工具schema不再暴露旧候选观察字段。
        ObservedBuildActions.model_validate(self.model_dump(exclude={"build_directory", "discard_dependencies"}))
        if any(s.step_id.startswith("forge-") for s in self.steps):
            raise ValueError("不能占用系统步骤标识")
        return self

def assemble_simple_plan(task: PublicBuildTask, proposal: ObservedBuildActions, *, revision=1) -> SimpleBuildPlan:
    """旧观察字段仍留作候选证据，不编译成Shell断言，不能改变共同裁判。"""
    steps = []
    for s in proposal.steps:
        if s.step_id.startswith("forge-"):
            raise PlanContractError("不能占用系统步骤标识")
        value = s.model_dump(exclude={"stdout_contains", "files_exist", "directories_exist"})
        steps.append(PlanStep(**value))
    return SimpleBuildPlan(task=task, revision=revision, steps=tuple(steps), build_directory=getattr(proposal, "build_directory", None), discard_dependencies=getattr(proposal, "discard_dependencies", {}))

def validate_simple_revision(current: SimpleBuildPlan, proposed: SimpleBuildPlan, *, allow_observation_only=False) -> str:
    """说明、步骤别名和观察提示的变化不能触发相同失败命令重跑。"""

    def execution(plan, *, reset=False):
        return [(s.role, s.command, s.workdir) for s in plan.steps if (s.step_id == "forge-generated-reset") == reset]

    if execution(current) == execution(proposed):
        new_reset = execution(proposed, reset=True)
        if not new_reset or new_reset == execution(current, reset=True):
            current_ids = [s.step_id for s in current.steps if s.step_id != "forge-generated-reset"]
            proposed_ids = [s.step_id for s in proposed.steps if s.step_id != "forge-generated-reset"]
            if allow_observation_only and proposed.build_directory is not None and proposed.build_directory != current.build_directory and proposed_ids == current_ids:
                return "observation"
            raise PlanContractError("恢复方案没有改变实际执行动作；不能仅改说明、步骤标识或构建目录来重跑相同失败。请读取真实失败日志，修正必要命令或工作目录；无法修复时明确说明阻塞。")
    return "execution"

def simple_agent_packet(task: PublicBuildTask, *, current_plan=None, handoff=None) -> dict:
    if current_plan is not None and current_plan.task != task:
        raise PlanContractError("恢复不能改变公开任务")
    if (current_plan is None) != (handoff is None):
        raise PlanContractError("当前方案与交接必须一起提供")
    if current_plan and (handoff.get("plan_sha256") != current_plan.fingerprint() or not handoff.get("handoff_id")):
        raise PlanContractError("交接与当前方案不匹配")
    public_plan = current_plan.model_dump(mode="json") if current_plan else None
    if public_plan:
        public_plan["steps"] = [{k: v for k, v in s.items() if k != "diagnostic_paths"} for s in public_plan["steps"] if not s["step_id"].startswith("forge-")]
        public_plan["plan_sha256"] = current_plan.fingerprint()
    return dict(task=task.model_dump(mode="json"), current_plan=public_plan, handoff=handoff)

def normalized_read_path(value: str, *, logs=False) -> str:
    """只为已授权的容器根提供别名；不扩展读取根或接受父目录穿越。"""
    path = PurePosixPath(value)
    if ".." in path.parts:
        raise PlanContractError("读取路径不能包含父目录跳转")
    if path.is_absolute():
        if logs:
            if path.parts[1:2] not in (("logs",), ("replay",)):
                raise PlanContractError("日志绝对路径仅允许/logs或/replay")
            value = path.as_posix().lstrip("/")
        else:
            try:
                value = path.relative_to("/workspace/repo").as_posix()
            except ValueError as exc:
                raise PlanContractError("源码绝对路径仅允许/workspace/repo内") from exc
    return value

def safe_readonly_tools(source_root, session_root):
    originals = {item.name: item for item in readonly_plan_tools(source_root, session_root)}

    def invoke(name, arguments):
        try:
            field = "directory" if name == "list_source" else "path"
            arguments[field] = normalized_read_path(arguments[field], logs=name == "read_failure_log")
            result = json.loads(originals[name].invoke(arguments))
            result["read_request"] = arguments
            return json.dumps(result, ensure_ascii=False)
        except (PlanContractError, OSError) as exc:
            # 拒绝无效操作但让Agent在下一次显式、计量的请求中纠正，不隐式重试工具。
            return json.dumps({"error": type(exc).__name__, "accepted": False, "reason": "路径越界、文件缺失或读取参数无效；先list_source核对规范路径", "read_request": arguments}, ensure_ascii=False)

    @tool
    def list_source(directory: str = ".") -> str:
        """列出源码目录的直接成员；支持相对路径或/workspace/repo内绝对路径；最多100项，错误返回反馈。"""
        return invoke("list_source", {"directory": directory})

    @tool
    def read_source(path: str, start_line: int = 1) -> str:
        """读取源码文本，支持相对路径或/workspace/repo内绝对路径；最多120行/8000字符，保留哈希与起始行。"""
        return invoke("read_source", {"path": path, "start_line": start_line})

    @tool
    def read_failure_log(path: str, start_line: int = 1) -> str:
        """读取Session内logs/或replay/日志；也接受/logs和/replay别名，不读取其他目录。"""
        return invoke("read_failure_log", {"path": path, "start_line": start_line})

    return [list_source, read_source, read_failure_log]

def readonly_plan_tools(source_root: Path, evidence_root: Path | None = None):
    @tool
    def list_source(directory: str = ".") -> str:
        """列出源码子目录的直接成员，最多100项；不读取宿主机或个人笔记。"""
        path = _inside(source_root, directory)
        names = sorted(child.name + ("/" if child.is_dir() else "") for child in path.iterdir() if child.name != ".git")
        return json.dumps({"entries": names[:100], "truncated": len(names) > 100})

    @tool
    def read_source(path: str, start_line: int = 1) -> str:
        """读取仓库文本文件，从指定行起最多120行/8000字符，附完整文件哈希。"""
        return _read_text(source_root, path, start_line)

    tools = [list_source, read_source]
    if evidence_root is not None:

        @tool
        def read_failure_log(path: str, start_line: int = 1) -> str:
            """读取交接所指向的 logs/ 或 replay/ 内文本日志；路径相对 Session 根。"""
            if PurePosixPath(path).parts[:1] not in (("logs",), ("replay",)):
                raise PlanContractError("仅开放执行及重建日志")
            resolved = _inside(evidence_root, path)
            if not any(resolved.is_relative_to((evidence_root / name).resolve()) for name in ("logs", "replay")):
                raise PlanContractError("日志链接逃出授权日志目录")
            return _read_text(evidence_root, path, start_line)

        tools.append(read_failure_log)
    return tools

def _read_text(root: Path, path: str, start_line: int) -> str:
    target = _inside(root, path)
    if start_line < 1 or not target.is_file() or target.stat().st_size > 16 * 1024 * 1024:
        raise PlanContractError("文件不可读、过大或起始行无效")
    content = target.read_bytes()
    lines = content.decode(errors="replace").splitlines()
    selected = lines[start_line - 1 : start_line + 119]
    text = "\n".join(f"{i}: {line}" for i, line in enumerate(selected, start_line))
    return json.dumps({"path": path, "sha256": hashlib.sha256(content).hexdigest(), "total_lines": len(lines), "content": text[:8000], "truncated": len(text) > 8000 or start_line + 119 < len(lines)}, ensure_ascii=False)

def observe_configuration(root: Path, system: str, *, directory: str | None = None) -> dict:
    """从实际Cache读取generator和源码，绝不固定要求Ninja。"""
    if system == "autotools":
        folder = root / (directory or ".")
        # GNU Make的标准入口；其他作者自定义入口保留unknown，由真实build反馈确认。
        entry = next((name for name in ("GNUmakefile", "makefile", "Makefile") if (folder / name).is_file()), None)
        return dict(status="passed" if (folder / "config.status").is_file() and entry else "unknown", directory=directory or ".", entry=entry, build_system=system)
    if system != "cmake":
        return dict(status="not_applicable", reason="当前入口不使用CMake/Autotools配置观察；主构建仍须独立产物检查", configurations=[], build_system=system)
    rows = []
    paths = [root / directory / "CMakeCache.txt"] if directory is not None else sorted(root.rglob("CMakeCache.txt"))
    for p in paths:
        if not p.is_file():
            continue
        if p.is_symlink() or not p.resolve().is_relative_to(root.resolve()):
            continue
        cache = {}
        for line in p.read_text(errors="replace").splitlines():
            if "=" in line and ":" in line.split("=", 1)[0]:
                key, value = line.split("=", 1)
                cache[key.split(":", 1)[0]] = value
        generator = cache.get("CMAKE_GENERATOR")
        entry = {"Unix Makefiles": "Makefile", "Ninja": "build.ninja", "Ninja Multi-Config": "build.ninja"}.get(generator)
        source = cache.get("CMAKE_HOME_DIRECTORY", "")
        directory = cache.get("CMAKE_CACHEFILE_DIR", "")
        expected_directory = "/workspace/repo/" + p.parent.relative_to(root).as_posix()
        expected_directory = expected_directory.removesuffix("/.")
        try:
            src = PurePosixPath(source).relative_to("/workspace/repo")
            source_valid = ".." not in src.parts and (root / src / "CMakeLists.txt").is_file()
        except ValueError:
            source_valid = False
        passed = bool(entry and (p.parent / entry).is_file() and source_valid and directory == expected_directory)
        rows.append(dict(directory=p.parent.relative_to(root).as_posix(), generator=generator, entry=entry, source_directory=source, cache_directory=directory, status="passed" if passed else "unknown" if not entry else "failed"))
    return dict(status="passed" if rows and all(r["status"] == "passed" for r in rows) else "unknown" if not rows or any(r["status"] == "unknown" for r in rows) else "failed", configurations=rows, build_system="cmake")

def configuration_entry(root: Path, step: PlanStep, previous: dict, *, output: str = "", build_directory: str | None = None) -> tuple[str, str | None]:
    """目录来自显式上下文或原生工具反馈；无法绑定时不猜Shell参数含义。"""
    system = previous.get("build_system", "make")
    directory = previous.get("directory") if step.role == "build" else None
    working = PurePosixPath(step.workdir).relative_to("/workspace/repo")
    if build_directory is not None:
        directory = PurePosixPath(build_directory).relative_to("/workspace/repo").as_posix()
    for segment in operations._shell_command_segments(step.command):
        invocation = operations._command_invocation(segment)
        if not invocation:
            continue
        executable, args = invocation
        name = PurePosixPath(executable).name
        if name not in {"cmake", "configure", "make", "gmake", "ninja", "scons", "meson"}:
            continue
        if name == "cmake":
            system = "cmake"
        elif name == "configure":
            system = "autotools"
        elif name in {"make", "gmake", "ninja"} and directory is None:
            # 没有已绑定的生成目录时，以实际构建入口替代初始扫描标签。
            system = "ninja" if name == "ninja" else "make"
        elif name in {"scons", "meson"}:
            system = name
    if system == "cmake":
        # 原生工具负责preset/宏/实际目录；终端日志缺失不等于配置失败。
        for line in output.splitlines():
            prefix = "-- Build files have been written to: "
            if line.startswith(prefix):
                value = PurePosixPath(line.removeprefix(prefix).strip())
                if not value.is_absolute() or not value.is_relative_to("/workspace/repo"):
                    raise PlanContractError("CMake报告的配置目录必须在仓库内")
                directory = value.relative_to("/workspace/repo").as_posix()
    elif directory is None:
        directory = working.as_posix()
    if directory is not None:
        absolute = (root / directory).resolve()
        if not absolute.is_relative_to(root.resolve()):
            raise PlanContractError("配置观察目录必须在仓库内")
        directory = absolute.relative_to(root.resolve()).as_posix()
    return system, directory

def validate_phase_command(step):
    """只把有明确作用域的make clean/distclean当阶段前置，保留其他阶段限制。"""
    from deerflow.tools.bound_compile_tools import _disables_strict_shell

    if _disables_strict_shell(step.command) or "/repro" in step.command:
        raise PlanContractError("不能关闭严格Shell或访问/repro")
    for segment in operations._shell_command_segments(step.command):
        invocation = operations._command_invocation(segment)
        if invocation and invocation[0] in {"rm", "unlink", "rmdir"}:
            raise PlanContractError("生成物清理由系统或作者clean目标执行，不能提交任意删除")
    roles = operations.infer_command_roles(step.command)
    if len(roles) <= 1:
        return
    expected = {"build"} if step.role == "build" else {"configure"} if step.role == "configure" else set()
    if roles != expected | {"housekeeping"}:
        raise PlanContractError("命令混合多个逻辑阶段")
    substantive = False
    for segment in operations._shell_command_segments(step.command):
        invocation = operations._command_invocation(segment)
        if not invocation:
            raise PlanContractError("清理前置必须能确定实际命令")
        executable, args = invocation
        if executable in {"make", "gmake"} and args in (["clean"], ["distclean"]):
            if substantive:
                raise PlanContractError("清理只能发生在当前阶段实际动作之前")
            continue
        if executable in {"rm", "unlink", "rmdir", "bash", "sh", "sudo", "env"}:
            raise PlanContractError("不能通过放宽清理前置执行任意删除或嵌套Shell")
        substantive = True

def generated_reset_step(baseline):
    """只清理本次源码树新增文件，不删除/重写原文件；同一显式动作进入重放。"""
    protected = sorted(baseline)
    script = """import os,pathlib
root=pathlib.Path('/workspace/repo')
protected=set(PROTECTED)
for directory,dirs,files in os.walk(root,topdown=False,followlinks=False):
 p=pathlib.Path(directory)
 if '.git' in p.relative_to(root).parts: continue
 for name in files:
  f=p/name; rel=f.relative_to(root).as_posix()
  if rel not in protected: f.unlink()
 for name in dirs:
  d=p/name; rel=d.relative_to(root).as_posix()
  if name=='.git' or rel in protected: continue
  if d.is_symlink(): d.unlink()
  elif not any(d.iterdir()): d.rmdir()
print('FORGE_GENERATED_RESET')
""".replace("PROTECTED", repr(protected))
    return PlanStep(
        step_id="forge-generated-reset", role="configure", command="python3 - <<'FORGE_RESET_PY'\n" + script + "\nFORGE_RESET_PY", source="系统：依赖/配置变化后清理原输入集合以外的生成文件", expected="物理清理与逻辑后缀失效分别记录"
    )

def primary_artifacts(*, task, reference, root, baseline, deadline):
    """独立组件覆盖＋结构/平台/来源检查；路径定位不改变构建动作。"""
    if reference.task_sha256 != _digest(task.model_dump(mode="json")):
        raise PlanContractError("独立参考与公开任务身份不一致")
    source_unchanged(root, baseline, reference.generated_documents)
    precompiled = set()
    for name, row in baseline.items():
        p = root / name
        if not p.is_symlink():
            with p.open("rb") as stream:
                magic = stream.read(8)
            if magic.startswith(b"\x7fELF") or magic == b"!<arch>\n":
                precompiled.add(row["sha256"])
    names = {n for c in reference.components for n in c.artifact_names}
    candidates = []
    machine = {"x86_64": "Advanced Micro Devices X86-64", "aarch64": "AArch64"}[task.architecture]
    for p in root.rglob("*"):
        if time.monotonic() >= deadline:
            return dict(status="unknown", reason="产物观察达到时限", components=[], artifacts=[])
        if p.name not in names or ".git" in p.relative_to(root).parts:
            continue
        try:
            resolved = p.resolve(strict=True)
        except (OSError, RuntimeError):
            continue
        if not resolved.is_relative_to(root.resolve()) or not resolved.is_file():
            continue
        relative = resolved.relative_to(root.resolve()).as_posix()
        if relative in baseline:
            continue
        kind = operations._classify_compiled_artifact(resolved, deadline=deadline)
        if kind not in {"executable", "static_library", "shared_library"}:
            continue
        digest = file_hash(resolved)
        if digest in precompiled:
            continue
        header = subprocess.run(["readelf", "-h", str(resolved)], capture_output=True, text=True, timeout=max(0.1, min(10, deadline - time.monotonic())), env={**os.environ, "LC_ALL": "C"})
        machines = {line.split(":", 1)[1].strip() for line in header.stdout.splitlines() if line.strip().startswith("Machine:")}
        if header.returncode != 0 or machines != {machine}:
            continue
        candidates.append(dict(alias=p.name, path=relative, kind=kind, size=resolved.stat().st_size, sha256=digest, mode=resolved.stat().st_mode & 0o777, platform=task.architecture, source="new_file_after_current_source_extraction"))
    rows, selected = [], []
    for component in reference.components:
        matches = [p for p in candidates if p["alias"] in component.artifact_names and p["kind"] in component.kinds]
        # 同一逻辑组件的静态/共享实现均可；逐内容身份去重副本/链接。
        identities = {(p["kind"], p["sha256"], p["mode"]): p for p in reversed(sorted(matches, key=lambda p: p["path"]))}
        covered = bool(identities)
        rows.append(dict(name=component.name, status="passed" if covered else "failed", evidence=component.evidence, candidates=list(identities.values())))
        selected.extend(identities.values())
    unique = {p["path"]: p for p in selected}
    return dict(status="passed" if all(r["status"] == "passed" for r in rows) else "failed", components=rows, artifacts=list(unique.values()))

def _retain_dependencies(self, plan):
    """遗漏不是删除；有效配方保留成功准备，不收集所有历史命令。"""
    successful = [s for s in self.plan.steps if s.role == "dependency" and s.step_id in self.completed]
    known = {s.step_id for s in successful}
    if not set(plan.discard_dependencies) <= known:
        raise PlanContractError("discard_dependencies只能引用当前已成功的依赖步骤")
    incoming = {s.step_id: s for s in plan.steps}
    retained = []
    keys = ("role", "command", "workdir", "requires", "required_output")
    for old in successful:
        if old.step_id in plan.discard_dependencies:
            continue
        new = incoming.get(old.step_id)
        if new is not None and any(getattr(old, k) != getattr(new, k) for k in keys):
            raise PlanContractError(f"替换成功依赖{old.step_id}须在discard_dependencies中说明理由；不能隐式覆盖")
        if any(s.step_id != old.step_id and (s.role, s.command, s.workdir) == (old.role, old.command, old.workdir) for s in plan.steps):
            raise PlanContractError(f"依赖改名没有改变实际执行动作；请沿用成功依赖的step_id={old.step_id}，不要改名重复执行")
        retained.append(new or old)
    retained_ids = {s.step_id for s in retained}
    # 成功环境准备保持实际先后，新增依赖在其后执行；配置后缀仍会失效。
    value = plan.model_dump()
    value["steps"] = [*retained, *(s for s in plan.steps if s.step_id not in retained_ids)]
    return SimpleBuildPlan.model_validate(value)

class PlanStep(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid", revalidate_instances="always")

    step_id: str = Field(pattern=r"^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")
    role: Literal["dependency", "configure", "build", "smoke", "artifact_stage"]
    command: str = Field(min_length=1)
    source: str = Field(min_length=1)
    expected: str = Field(min_length=1)
    workdir: str = "/workspace/repo"
    requires: tuple[str, ...] = ()
    required_output: tuple[str, ...] = ()
    diagnostic_paths: tuple[str, ...] = ()

    @field_validator("workdir")
    @classmethod
    def validate_workdir(cls, value: str) -> str:
        path = PurePosixPath(value)
        if value != path.as_posix() or ".." in path.parts or not any(path.is_relative_to(root) for root in ("/workspace/repo", "/artifacts")):
            raise ValueError("执行目录必须是仓库或交付目录内的规范绝对路径")
        return value

    @field_validator("diagnostic_paths")
    @classmethod
    def validate_diagnostics(cls, values: tuple[str, ...]) -> tuple[str, ...]:
        for value in values:
            _relative_path(value)
        return values

    @model_validator(mode="after")
    def validate_expectation(self) -> Self:
        if any(not marker for marker in self.required_output) or (self.role == "smoke" and not self.required_output):
            raise ValueError("任务验证必须提供非空输出依据，不能仅凭退出码判定实际运行过测试")
        return self

def _request_handoff(self, reason: str, step: PlanStep | None = None) -> dict:
    if self.handoffs_used >= self.budget.max_handoffs or self.commands_used >= self.budget.max_commands or self._remaining() <= 0:
        self.status = "budget_exhausted"
    else:
        self.handoffs_used += 1
        self.status = "needs_handoff"
        self.handoff = {
            "handoff_id": uuid.uuid4().hex,
            "reason": reason,
            "step_id": step.step_id if step else None,
            "plan_sha256": self.plan.fingerprint(),
            "command_frontier": self._expected_frontier,
            "recent_commands": [self._command_evidence(row) for row in self._session.commands[-6:]],
            "return_contract": "返回完整修订方案及修改理由；禁止自行降低验收或宣告成功",
        }
        (self.directory / f"handoff-{self.handoff['handoff_id']}.json").write_text(json.dumps(self.handoff, ensure_ascii=False, indent=2) + "\n")
    self._persist()
    return self.snapshot()

def run(self) -> dict:
    with self.manager.session_lock(self.thread_id, self.session_id):
        self._observe()
        if self.status != "pending":
            return self.snapshot()
        for step in self.plan.steps:
            if step.step_id in self.completed:
                continue
            if self.commands_used >= self.budget.max_commands or self._remaining() <= 0:
                self.status = "budget_exhausted"
                break
            if not set(step.requires).issubset(self.completed):
                return self._request_handoff("precondition_missing", step)
            self._observe()
            if not self._execute(step):
                return self._request_handoff("step_failed_or_expectation_missing", step)
            self._persist()
        else:
            self.status = "ready_for_verification"
        self._persist()
        return self.snapshot()

def apply_revision(self, *, handoff_id: str, plan: BuildPlan, reason: str) -> None:
    with self.manager.session_lock(self.thread_id, self.session_id):
        self._observe()
        plan = self.plan_model.model_validate(plan)
        if self.status != "needs_handoff" or not self.handoff or self.handoff["handoff_id"] != handoff_id or not reason.strip():
            raise PlanContractError("没有匹配的活动交接或修改理由")
        old = self.plan
        identity = ("plan_id", "repository_url", "commit_sha", "image_id", "source_archive_sha256", "build_system", "artifact_paths")
        if any(getattr(plan, key) != getattr(old, key) for key in identity) or plan.revision != old.revision + 1:
            raise PlanContractError("修订不得改变任务身份、交付要求或跳过版本")
        if tuple(s for s in plan.steps if s.role == "smoke") != tuple(s for s in old.steps if s.role == "smoke"):
            raise PlanContractError("修订不得降低或替换任务验证要求")
        prefix = 0
        for before, after in zip(old.steps, plan.steps):
            keys = ("step_id", "command", "role", "workdir", "requires", "required_output")
            if any(getattr(before, key) != getattr(after, key) for key in keys):
                break
            prefix += 1
        if prefix == len(old.steps) == len(plan.steps):
            raise PlanContractError("无变化修订不能触发相同失败的重复执行")
        keep = {step.step_id for step in old.steps[:prefix]}
        self.completed = {key: value for key, value in self.completed.items() if key in keep}
        self.plan = plan
        self.status = "pending"
        self.handoff = None
        self._write_plan()
        self.manager.log_event(self._session, "plan.revised", revision=plan.revision, reason=reason, retained_steps=sorted(keep))
        self._persist()

def _shell_command_segments(command: str) -> list[list[str]]:
    try:
        lexer = shlex(command.replace("\n", ";"), posix=True, punctuation_chars="();&|")
        lexer.whitespace_split = True
        lexer.commenters = ""
        tokens = list(lexer)
    except ValueError:
        return []

    segments: list[list[str]] = []
    current: list[str] = []
    for token in tokens:
        if token in _SHELL_COMMAND_SEPARATORS:
            if current:
                segments.append(current)
                current = []
            continue
        current.append(token)
    if current:
        segments.append(current)
    return segments

def _command_invocation(segment: list[str]) -> tuple[str, list[str]] | None:
    wrappers = {"command", "env", "sudo", "time"}
    for index, token in enumerate(segment):
        if token in {"if", "then", "elif", "else", "!", "while", "until", "do"}:
            continue
        if token == "--" or token.startswith("-") or re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", token):
            continue
        executable = PurePosixPath(token).name
        # command -v/-V 查询工具存在性，不执行后面的工具；其他分段仍须分析。
        if executable == "command":
            for argument in segment[index + 1 :]:
                if not argument.startswith("-") or argument == "--":
                    break
                if set(argument[1:]) & {"v", "V"}:
                    return None
        if executable in wrappers:
            continue
        return executable, segment[index + 1 :]
    return None

def _infer_command_roles(command: str, *, depth: int) -> set[str]:
    roles: set[str] = set()
    stages_artifacts = _command_mentions_container_path(command, "/artifacts")
    for segment in _shell_command_segments(command):
        invocation = _command_invocation(segment)
        if invocation is None:
            continue
        executable, arguments = invocation
        segment_text = " ".join(segment)

        if executable in _DEPENDENCY_SETUP_EXECUTABLES:
            roles.add("dependency_setup")
        if executable == "sleep":
            roles.add("replay_delay")

        if executable == "cmake":
            if "--build" in arguments:
                roles.add("build" if _cmake_invokes_real_build(arguments) else "housekeeping")
            elif "--install" not in arguments and "-E" not in arguments and "--open" not in arguments:
                roles.add("configure")
            if stages_artifacts and ("--install" in arguments or ("-E" in arguments and any(argument in {"copy", "copy_if_different"} for argument in arguments))):
                roles.add("artifact_stage")
            continue

        if executable in {"make", "gmake", "ninja"}:
            installs_artifacts = stages_artifacts and "install" in arguments
            if installs_artifacts:
                roles.add("artifact_stage")
            else:
                roles.add("build" if _build_tool_invokes_real_target(arguments) else "housekeeping")
            continue

        if executable in {"configure", "autogen.sh", "autoreconf"}:
            roles.add("configure")
            continue

        if stages_artifacts and executable in {"cp", "install"}:
            roles.add("artifact_stage")
            continue

        if executable in {"bash", "sh"}:
            if any(PurePosixPath(argument).name in {"configure", "autogen.sh"} for argument in arguments):
                roles.add("configure")
            inline_command = next(
                (arguments[index + 1] for index, argument in enumerate(arguments[:-1]) if argument.startswith("-") and "c" in argument[1:]),
                None,
            )
            if inline_command is not None and depth < 2:
                roles.update(_infer_command_roles(inline_command, depth=depth + 1))

        if stages_artifacts and re.search(r"(?:^|\s)(?:cp|install)\s", segment_text) is not None:
            roles.add("artifact_stage")

    return roles

def infer_command_roles(command: str) -> set[str]:
    """Infer every control-plane role present in a possibly compound shell command."""

    return _infer_command_roles(command, depth=0)

def compact_group(self, group, meter):
    """完整移出AI及配对Tool后另起证据消息，不发送悬空调用或截断推理字段。"""
    raw = [m.model_dump(mode="json") for m in group]
    self.group_compactions += 1
    # 初始规划与各次恢复共用账本；请求序号避免新任务重置组号后撞名。
    path = f"context-request-{meter._request_sequence + 1}-group-{self.group_compactions}.json"
    meter.ledger.save(path, raw)
    evidence = []
    calls = []
    notes = []
    for message in group:
        if message.type == "ai":
            calls.extend(message.tool_calls)
            if message.content:
                notes.append(bounded_text(str(message.content), 600))
        elif message.type == "tool":
            content = str(message.content)
            try:
                row = json.loads(content)
            except ValueError:
                row = {"preview": content}
            if isinstance(row, dict):
                row = {k: bounded_text(v, 1600) if isinstance(v, str) else v for k, v in row.items()}
            if len(json.dumps(row, ensure_ascii=False).encode()) > 4000:
                row = dict(preview=bounded_text(content, 2000), read_request=row.get("read_request") if isinstance(row, dict) else None)
            evidence.append(dict(tool=message.name, result=row, original_bytes=len(content.encode()), original_sha256=hashlib.sha256(content.encode()).hexdigest()))
    payload = dict(
        context_compaction=True,
        note="上一组AI及其工具结果已完整移出；以下为实际返回的有界片段，不是新工具执行或新的成功结论。必要时按read_request补读源码/日志。原推理与结果保存在独立原件中。",
        original_record=path,
        original_sha256=hashlib.sha256(json.dumps(raw, ensure_ascii=False).encode()).hexdigest(),
        calls=calls,
        assistant_notes=notes,
        evidence=evidence,
    )
    meter.ledger.append("planning.group_compacted", record=path, original_messages=len(group), original_sha256=payload["original_sha256"])
    return [HumanMessage(content=json.dumps(payload, ensure_ascii=False))]
